println("\n📊 REALISTIC DATASET GENERATION...")

function generate_REALISTIC_medical_data(n::Int)
    Random.seed!(42)
    
    println("   Generating $n patients with business constraints...")
    
    # AGE: Normal distribution (peak 40-50 years)
    age_raw = round.(Int, rand(Normal(50, 15), n))
    age = [clamp(a, 18, 90) for a in age_raw]
    age = [rand() < 0.05 ? missing : a for a in age]  # 5% missing
    
    # GENDER: Few missing (administrative info)
    gender = rand(["M", "F"], n)
    gender = [rand() < 0.02 ? missing : g for g in gender]  # 2% missing
    
    # BLOOD PRESSURE: Correlated with age
    # Elderly (>60): systematic measurement (5% missing)
    # Young (<30): rarely measured (40% missing)
    blood_pressure = Vector{Union{Int, Missing}}(undef, n)
    for i in 1:n
        if ismissing(age[i])
            blood_pressure[i] = missing
        elseif age[i] > 60
            blood_pressure[i] = rand() < 0.95 ? rand(130:160) : missing
        elseif age[i] < 30
            blood_pressure[i] = rand() < 0.60 ? missing : rand(110:130)
        else
            blood_pressure[i] = rand() < 0.80 ? rand(120:140) : missing
        end
    end
    
    # BMI and WEIGHT/HEIGHT: If one is missing, the other is missing too (strong correlation)
    has_weight_data = rand(n) .< 0.75  # 75% have weight data
    bmi = Vector{Union{Float64, Missing}}(undef, n)
    for i in 1:n
        bmi[i] = has_weight_data[i] ? rand([18.5, 22.0, 25.0, 27.5, 30.0, 32.5]) : missing
    end
    
    # DIABETES and GLUCOSE: Strongly correlated
    # If diabetes detected → glucose ALWAYS measured
    # If no diabetes → glucose rarely measured
    diabetes = Vector{Union{Bool, Missing}}(undef, n)
    glucose = Vector{Union{Float64, Missing}}(undef, n)
    
    for i in 1:n
        # 40% of patients have diabetes test
        if rand() < 0.40
            diabetes[i] = rand() < 0.15  # 15% are diabetic
            if diabetes[i]
                glucose[i] = rand(140:200)  # Diabetics: high glucose
            else
                glucose[i] = rand() < 0.7 ? rand(80:110) : missing  # 30% not measured anyway
            end
        else
            diabetes[i] = missing
            glucose[i] = missing  # If diabetes not tested, glucose not measured
        end
    end
    
    # SMOKER: Correlated with age
    # <18 years: always false (legal constraint)
    # >70 years: often declared (more honest generation)
    smoker = Vector{Union{Bool, Missing}}(undef, n)
    for i in 1:n
        if ismissing(age[i])
            smoker[i] = rand() < 0.3 ? missing : rand(Bool)
        elseif age[i] < 18
            smoker[i] = false  # NEVER missing for minors
        elseif age[i] > 70
            smoker[i] = rand() < 0.9 ? rand(Bool) : missing  # 90% declare
        else
            smoker[i] = rand() < 0.7 ? rand(Bool) : missing  # 30% refuse
        end
    end
    
    # CHOLESTEROL: Expensive test, more frequent for >50 years
    cholesterol = Vector{Union{Int, Missing}}(undef, n)
    for i in 1:n
        if ismissing(age[i])
            cholesterol[i] = missing
        elseif age[i] > 50
            cholesterol[i] = rand() < 0.70 ? rand(150:260) : missing
        else
            cholesterol[i] = rand() < 0.30 ? rand(150:220) : missing
        end
    end
    
    # BLOOD TYPE: System error, 100% missing (realistic: data migration bug)
    blood_type = fill(missing, n)
    
    # VISIT DATE and PATIENT ID: Never missing (primary keys)
    visit_date = fill(Date(2024, 1, 1), n)
    patient_id = 1:n
    
    return DataFrame(
        PatientID = patient_id,
        Age = age,
        Gender = gender,
        BloodPressure = blood_pressure,
        Cholesterol = cholesterol,
        BMI = bmi,
        Smoker = smoker,
        Diabetes = diabetes,
        Glucose = glucose,
        BloodType = blood_type,
        VisitDate = visit_date
    )
end

